import { test, expect, type APIRequestContext } from '@playwright/test';

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status()).toBe(200);
  const sendJson = await sendRes.json();
  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status()).toBe(200);
  return (await verifyRes.json()).user;
}

test.describe.serial('帖子多途径分享与站内私信分享基础 E2E 套件', () => {
  test('1. 帖子卡片与详情页多途径分享菜单（复制链接、复制分享文案）', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await loginUser(page.request, makeEmail('share-menu'), '多途径测试员');

    const postText = `多途径分享测试动态-${Date.now()}`;
    const createRes = await page.request.post('/api/posts', { data: { content: postText } });
    expect(createRes.status()).toBe(201);
    const postId = (await createRes.json()).post.id;

    await page.goto('/');
    const card = page.locator('article').filter({ hasText: postText }).first();
    await expect(card).toBeVisible({ timeout: 10000 });

    const shareBtn = card.getByRole('button', { name: /分享/i }).first();
    await shareBtn.click();

    const menu = page.getByRole('menu').first();
    await expect(menu).toBeVisible();
    await expect(menu.getByRole('menuitem', { name: /复制链接/i }).first()).toBeVisible();
    await expect(menu.getByRole('menuitem', { name: /私信/i }).first()).toBeVisible();

    const sharePromise = page.waitForResponse(
      (res) => res.url().includes(`/api/posts/${postId}/share`) && res.request().method() === 'POST'
    );
    await menu.getByRole('menuitem', { name: /复制链接/i }).first().click();
    const shareRes = await sharePromise;
    expect(shareRes.status()).toBe(200);
    const shareJson = await shareRes.json();
    expect(shareJson.sharesCount).toBe(1);
  });

  test('2. 帖子通过站内私信分享给好友并在私信中点击动态卡片直达原帖', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const ctxB = await browser.newContext();
    try {
      const suffix = Date.now().toString().slice(-4);
      const userA = await loginUser(page.request, makeEmail('dm-share-a'), `分享人${suffix}`);
      const userB = await loginUser(ctxB.request, makeEmail('dm-share-b'), `好友小乙${suffix}`);

      await page.request.post(`/api/users/${userB.id}/follow`);

      const postText = `推荐阅读的架构笔记-${Date.now()}`;
      const createRes = await page.request.post('/api/posts', { data: { content: postText } });
      expect(createRes.status()).toBe(201);
      const postId = (await createRes.json()).post.id;

      await page.goto(`/posts/${postId}`);
      const detailDialog = page.getByRole('dialog').first();
      await expect(detailDialog).toBeVisible({ timeout: 10000 });

      await detailDialog.getByRole('button', { name: /分享/i }).first().click();
      const menu = page.getByRole('menu').first();
      await expect(menu).toBeVisible();
      await menu.getByRole('menuitem', { name: /私信/i }).first().click();

      const dmShareDialog = page.getByRole('dialog').last();
      await expect(dmShareDialog).toBeVisible({ timeout: 10000 });

      const searchInput = dmShareDialog.getByPlaceholder(/搜索/i).first();
      await searchInput.fill(userB.nickname);
      const recipientBtn = dmShareDialog.getByText(userB.nickname).first();
      await expect(recipientBtn).toBeVisible({ timeout: 8000 });
      await recipientBtn.click();

      const noteText = `这篇很实用快看看-${suffix}`;
      const noteInput = dmShareDialog.getByPlaceholder(/附言|留言|说点什么/i).first();
      await noteInput.fill(noteText);

      const shareDmPromise = page.waitForResponse(
        (res) => res.url().includes(`/api/posts/${postId}/share-dm`) && res.request().method() === 'POST'
      );
      await dmShareDialog.getByRole('button', { name: /发送/i }).last().click();
      const shareDmRes = await shareDmPromise;
      expect(shareDmRes.status()).toBe(201);

      const pageB = await ctxB.newPage();
      await pageB.setViewportSize({ width: 1440, height: 900 });
      await pageB.goto('/messages');
      const convItem = pageB.getByText(userA.nickname).first();
      await expect(convItem).toBeVisible({ timeout: 10000 });
      await convItem.click();

      await expect(pageB.getByText(noteText).first()).toBeVisible({ timeout: 10000 });
      const sharedCard = pageB.getByText(postText).first();
      await expect(sharedCard).toBeVisible({ timeout: 10000 });
      await sharedCard.click();

      const openedDetail = pageB.getByRole('dialog').first();
      await expect(openedDetail).toBeVisible({ timeout: 10000 });
      await expect(openedDetail).toContainText(postText);
      await pageB.close();
    } finally {
      await ctxB.close();
    }
  });
});
